argsort' :: (HasCallStack, Ord a, G.Vector v a, G.Vector v Int) => v a -> v Int
argsort' xs =
  G.modify
    (VAI.sortBy (\i j -> compare (xs G.! i) (xs G.! j) <> compare i j))
    $ G.generate (G.length xs) id

solve :: StateT BS.ByteString IO ()
solve = do
  -- m players will be selected
  (!n, !m, !k) <- ints3P

  t <- lineP
  ss <- V.replicateM n $ do
    s <- lineP
    pure . U.fromList $ BS.zipWith (==) s t

  -- What property is monotonically increasing?
  -- - first win: yes. but it doesn't always mean when it becomes a qualifier.
  -- -
  -- let firstMatches :: U.Vector Int = U.convert $ V.map (U.length . U.dropWhile not) ss

  -- Greedy answer
  -- - match by true. so, sorting makes sense. (suffix array?)
  --
  -- If we sort, we know which one comes to the first?
  -- - What about bisecting the new position?

  -- smaller ones come first. (not comfortable, need argsortBy/sortIndicesBy)
  let is' = argsort' ss
  let !_ = dbg $ V.modify VAI.sort ss

  -- 同率正解者が M の枠を超える位置にいる場合、落ちる気がする
  -- strict に bisect すれば問題無い
  --
  -- それぞれのクエリは副作用を場に残す、、本質的に multiset だった

  q <- intP
  replicateM_ q $ do
    (!i, !j) <- ints11P
    let !s1' = U.accumulate xor (ss G.! i) $ U.singleton (j, True)
    let iAt = maxRight 0 n $ \i ->
          if i == 0
            then True
            else ss G.! (is' G.! (i - 1)) < s1'
    -- 0 1 2 3 4
    --     <--->
    --     2 1 0
    let rank = n - iAt
    let rank'
          | ss G.! i U.! j = rank - 1 -- It's the one updated
          | otherwise = rank
    let !_ = dbg ((i, j), s1', "i", (i, iAt), "rank", (rank, rank'), rank' < m)
    printYn $ U.or s1' && rank' < m

-- verification-helper: PROBLEM https://atcoder.jp/contests/abc475/tasks/abc475_e
main :: IO ()
main = runIO solve
